const JSZip = require("jszip");

const TEMPLATE_B64 = "";

// ── XML helpers ────────────────────────────────────────────────────────────

function escXml(str) {
  return String(str || "")
    .replace(/&/g, "&amp;").replace(/</g, "&lt;").replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;").replace(/'/g, "&apos;");
}

function fmtDate(d) {
  if (!d) return "";
  try {
    return new Date(d + "T00:00:00").toLocaleDateString("en-FJ", {
      day: "numeric", month: "long", year: "numeric"
    });
  } catch { return d; }
}

// Search backwards from `before` for actual <tag> or <tag ...> (not <tagXxx>)
function lastTag(xml, tag, before) {
  const marker = "<" + tag;
  let pos = before;
  while (pos >= 0) {
    pos = xml.lastIndexOf(marker, pos - 1);
    if (pos === -1) return -1;
    const next = xml[pos + marker.length];
    if (next === ">" || next === " ") return pos;
  }
  return -1;
}

// Find the matching close tag, depth-tracking
function findClose(xml, start, tag) {
  const open = "<" + tag, close = "</" + tag + ">";
  let depth = 0, i = start;
  while (i < xml.length) {
    if (xml.startsWith(open, i)) {
      const next = xml[i + open.length];
      if (next === ">" || next === " ") { depth++; i += open.length; continue; }
    }
    if (xml.startsWith(close, i)) {
      depth--;
      if (depth === 0) return i;
      i += close.length; continue;
    }
    i++;
  }
  return xml.length;
}

function removePara(xml, token) {
  const idx = xml.indexOf(token);
  if (idx === -1) return xml;
  const pStart = lastTag(xml, "w:p", idx);
  if (pStart === -1) return xml;
  const pEnd = findClose(xml, pStart, "w:p") + 6; // </w:p> = 6 chars
  return xml.slice(0, pStart) + xml.slice(pEnd);
}

function expandLoop(xml, items) {
  xml = removePara(xml, "{#items}");
  const idx = xml.indexOf("{{ITEM_NO}}");
  if (idx === -1) return removePara(xml, "{/items}");

  const trStart = lastTag(xml, "w:tr", idx);
  if (trStart === -1) return removePara(xml, "{/items}");
  const trEnd = findClose(xml, trStart, "w:tr") + 7; // </w:tr> = 7 chars
  const tmpl = xml.slice(trStart, trEnd);

  const rows = items
    .filter(i => i.description && i.description.trim())
    .map((item, n) => tmpl
      .replaceAll("{{ITEM_NO}}",    escXml(String(n + 1)))
      .replaceAll("{{DESCRIPTION}}",escXml(item.description))
      .replaceAll("{{QTY}}",        escXml(String(item.qty || "")))
      .replaceAll("{{UNIT}}",       escXml(item.unit || ""))
      .replaceAll("{{RATE}}",       "")
      .replaceAll("{{VIP_RATE}}",   "")
      .replaceAll("{{COMMENTS}}",   "")
    ).join("");

  xml = xml.slice(0, trStart) + rows + xml.slice(trEnd);
  return removePara(xml, "{/items}");
}

async function generateDoc(supplierName, form, items) {
  const templateBuf = Buffer.from(TEMPLATE_B64, "base64");
  const zip = await JSZip.loadAsync(templateBuf);

  const tokens = {
    "{{PROJECT}}":       escXml(form.project),
    "{{BRBN}}":          escXml(form.brbn),
    "{{DATE}}":          escXml(fmtDate(form.date)),
    "{{SCOPE_OF_WORKS}}":escXml(form.scope || ""),
    "{{CLOSING_TIME}}":  escXml(form.closingTime),
    "{{CLOSING_DATE}}":  escXml(fmtDate(form.closingDate)),
  };

  let doc = await zip.file("word/document.xml").async("string");
  for (const [k, v] of Object.entries(tokens)) doc = doc.replaceAll(k, v);
  doc = expandLoop(doc, items);
  zip.file("word/document.xml", doc);

  for (const fname of ["word/footer1.xml", "word/footer2.xml"]) {
    let f = await zip.file(fname).async("string");
    f = f.replaceAll("{{BRBN}}",    escXml(form.brbn))
         .replaceAll("{{PROJECT}}", escXml(form.project))
         .replaceAll("{{DATE}}",    escXml(fmtDate(form.date)));
    zip.file(fname, f);
  }

  return zip.generateAsync({ type: "nodebuffer", compression: "DEFLATE" });
}

// ── Handler ────────────────────────────────────────────────────────────────

exports.handler = async (event) => {
  const cors = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "Content-Type",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
  };

  if (event.httpMethod === "OPTIONS") return { statusCode: 200, headers: cors, body: "" };
  if (event.httpMethod !== "POST")   return { statusCode: 405, headers: cors, body: "Method Not Allowed" };

  try {
    const { form, items, suppliers } = JSON.parse(event.body);
    const files = [];

    for (const supplier of suppliers) {
      const buf = await generateDoc(supplier.name, form, items);
      const brbnSafe = form.brbn.replace(/\//g, "-");
      const nameSafe = supplier.name.replace(/\s+/g, "_").replace(/[^A-Za-z0-9_-]/g, "");
      files.push({
        supplierId:   supplier.id,
        supplierName: supplier.name,
        filename:     `RFQ_BRBN${brbnSafe}_${nameSafe}.docx`,
        contentB64:   buf.toString("base64"),
      });
    }

    return {
      statusCode: 200,
      headers: { ...cors, "Content-Type": "application/json" },
      body: JSON.stringify({ files }),
    };
  } catch (err) {
    console.error("generate-rfq error:", err);
    return {
      statusCode: 500,
      headers: { ...cors, "Content-Type": "application/json" },
      body: JSON.stringify({ error: err.message }),
    };
  }
};
